effect.shader:
vec4 gmExtract(vec4 c){float l=max(max(c.r,c.g),c.b);float x=max(l-threshold,0.0)+softKnee*log(1.0+exp((l-threshold)/max(softKnee,0.001)));return vec4(c.rgb*x/max(l,0.0001),c.a);}
vec4 gmBlur(sampler2D tex,vec2 uv,vec2 stepUv){vec4 s=vec4(0.0);float w=0.0;for(int i=-12;i<=12;i++){float x=float(i)/12.0;float k=exp(-x*x*3.2);s+=texture2DCv(tex,clamp(uv+stepUv*float(i),0.0,1.0))*k;w+=k;}return s/w;}
void main(){
vec2 uv=acScreenNorm;
if(acPass==0){vec2 sz=max(inputImg.size,vec2(1.0));gl_FragColor=gmBlur(inputImg.texture,uv,vec2(radiusPx/12.0/sz.x,0.0));gl_FragColor=gmExtract(gl_FragColor);return;}
if(acPass==1){vec2 sz=max(blurH.size,vec2(1.0));gl_FragColor=gmBlur(blurH.texture,uv,vec2(0.0,radiusPx/12.0/sz.y));return;}
vec4 src=texture2DCv(inputImg.texture,uv),g=texture2DCv(blurV.texture,uv);float l=dot(g.rgb,vec3(0.2126,0.7152,0.0722));g.rgb=mix(vec3(l),g.rgb,saturation)*glowColor.rgb*intensity;
vec3 outRgb=src.rgb+g.rgb;gl_FragColor=vec4(mix(src.rgb,outRgb,mixAmount),src.a+clamp(g.a*intensity,0.0,1.0)*mixAmount*(1.0-src.a));
}
